parameters.jsCode:
const imageUrl = $json?.choices?.[0]?.message?.images?.[0]?.image_url?.url;

if (!imageUrl) {
  throw new Error('Image URL was not returned by Gemini');
}

const base64 = imageUrl.replace(/^data:image\/[^;]+;base64,/, '');

return {
  json: {
    ...$json,
    image_base64: base64,
  },
};
